export function initWeatherFavorites({root,db,esc,onSelect,onRestore,getPlace}){
 let uid=null,rows=[],prefs={layer:'rain',rain_hours:24,home_key:null},epoch=0,revision=0,busy=false,message='',queue=Promise.resolve();
 const key=p=>`${Number(p.latitude).toFixed(3)},${Number(p.longitude).toFixed(3)}`;
 function render(){const p=getPlace(),saved=p&&rows.some(r=>r.place_key===key(p)),home=rows.find(r=>r.place_key===prefs.home_key)||rows[0];root.innerHTML=`<h3>Mis lugares</h3><button id="weather-save" ${busy||!p?'disabled':''}>${uid?(saved?'★ Quitar de favoritos':'☆ Guardar lugar'):'Ingresar para guardar favoritos'}</button><p role="status">${esc(message)}</p><div class="weather-favorites-list">${rows.map((r,i)=>`<button data-weather-favorite="${i}"><strong>${esc(r.name)}${r===home?' · Inicio':''}</strong><small>${esc(r.region)}</small></button>`).join('')}</div>${uid?'<small>El último favorito que abras será tu lugar de inicio. Capa y periodo sincronizados con Convergencia.</small>':''}`;
 root.querySelector('#weather-save').onclick=async()=>{if(!uid){document.getElementById('feed-account')?.click();return;}const p=getPlace();if(!p||busy)return;const owner=uid,token=epoch;busy=true;message='Guardando…';render();try{const query=db.from('atlas_dev_weather_favorites');const result=saved?await query.delete().eq('user_id',owner).eq('place_key',key(p)):await query.upsert({user_id:owner,place_key:key(p),name:p.name,region:p.region||'',latitude:p.latitude,longitude:p.longitude,timezone:p.timezone||'UTC'},{onConflict:'user_id,place_key'});if(token!==epoch)return;if(result.error)throw result.error;if((saved&&prefs.home_key===key(p))||(!saved&&!rows.length))await remember({home_key:saved?null:key(p)});message=saved?'Lugar quitado de favoritos.':'Guardado en tu cuenta.';await refresh();}catch{if(token===epoch)message='No se pudo guardar. Reintenta.';}finally{if(token===epoch){busy=false;render();}}};
 root.querySelectorAll('[data-weather-favorite]').forEach(b=>b.onclick=()=>{const p=rows[Number(b.dataset.weatherFavorite)];remember({home_key:p.place_key});onSelect(p);});}
 function remember(patch){if(!uid)return Promise.resolve();const token=epoch,owner=uid;revision++;prefs={...prefs,...patch};message='Sincronizando preferencias…';render();queue=queue.catch(()=>{}).then(async()=>{if(token!==epoch)return;const {error}=await db.from('atlas_dev_weather_preferences').upsert({user_id:owner,...patch},{onConflict:'user_id'});if(token!==epoch)return;message=error?'No se pudieron guardar las preferencias. Vuelve a elegir la capa o el favorito.':'Preferencias guardadas en tu cuenta.';render();});return queue;}
 async function refresh(restore=false){await queue.catch(()=>{});if(!uid)return;const token=epoch,rev=revision,owner=uid;try{const [favorites,settings]=await Promise.all([db.from('atlas_dev_weather_favorites').select('place_key,name,region,latitude,longitude,timezone').eq('user_id',owner).order('created_at'),db.from('atlas_dev_weather_preferences').select('home_key,layer,rain_hours').eq('user_id',owner).maybeSingle()]);if(token!==epoch||rev!==revision)return;if(favorites.error||settings.error)throw Error();rows=favorites.data||[];prefs={layer:'rain',rain_hours:24,home_key:null,...settings.data};render();if(restore)onRestore?.({place:rows.find(r=>r.place_key===prefs.home_key)||rows[0]||null,...prefs});}catch{if(token===epoch){message='No se pudieron sincronizar tus lugares. Reintenta al volver a Clima.';render();}}}
 async function session(user){const next=user?.id||null;if(next===uid)return;epoch++;revision++;uid=next;rows=[];prefs={layer:'rain',rain_hours:24,home_key:null};busy=false;message='';render();if(uid)await refresh(true);else onRestore?.({place:null,layer:'rain',rain_hours:24});}
 const ready=db?db.auth.getSession().then(({data})=>session(data?.session?.user)):Promise.resolve();
 if(db)db.auth.onAuthStateChange((_,s)=>setTimeout(()=>session(s?.user),0));render();document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});return {render,refresh,remember,ready};
}
